import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o,af as n}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"Qwen tutorial","description":"Audience: frontend engineers opening qianwen.com for the first time. You will send the first prompt and know the official desktop / App doors.","frontmatter":{"title":"Qwen tutorial","description":"Audience: frontend engineers opening qianwen.com for the first time. You will send the first prompt and know the official desktop / App doors.","domain":"product","tags":["chat"],"role":"tutorial"},"headers":[],"relativePath":"products/qwen/qwen.md","filePath":"products/qwen/qwen.md","lastUpdated":1787110548000}'),r={name:"products/qwen/qwen.md"};function i(s,e,l,d,p,c){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="qwen-tutorial" tabindex="-1">Qwen tutorial <a class="header-anchor" href="#qwen-tutorial" aria-label="Permalink to &quot;Qwen tutorial&quot;">​</a></h1><blockquote><p>Start at <a href="https://www.qianwen.com/" target="_blank" rel="noreferrer">qianwen.com</a> or the <a href="https://www.qianwen.com/download" target="_blank" rel="noreferrer">PC client page</a>. This page only repeats entries and capabilities you can check on official pages.</p></blockquote><h2 id="goals-and-non-goals" tabindex="-1">Goals and non-goals <a class="header-anchor" href="#goals-and-non-goals" aria-label="Permalink to &quot;Goals and non-goals&quot;">​</a></h2><p><strong>Audience:</strong> frontend engineers opening Qwen for the first time. The home button says <strong>登录</strong>; use whatever method the page actually offers.</p><p><strong>You will:</strong> send a first prompt on web or a client, and know how to get the desktop app and the official mobile apps.</p><p><strong>You will not:</strong> get a Taobao / Alipay signup guide, a Lingma / Qoder install, a Bailian API walkthrough, or invented membership prices.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>You can reach <code>www.qianwen.com</code> (some resolvers map it into <code>198.18.0.0/15</code>; change DNS / disable Fake-IP before calling it down).</li><li>OS floors come from official pages — do not merge them: <ul><li>App Store: <strong>iOS 14.0</strong> or later; iPad needs <strong>iPadOS 14.0</strong> or later.</li><li>Windows / Mac / Android / HarmonyOS numeric floors were <strong>not</strong> readable on the download page or the agreement on 2026-08-19. </li></ul></li></ul><h2 id="open-it-in-15-minutes" tabindex="-1">Open it in 15 minutes <a class="header-anchor" href="#open-it-in-15-minutes" aria-label="Permalink to &quot;Open it in 15 minutes&quot;">​</a></h2><h3 id="_1-pick-an-official-door" tabindex="-1">1. Pick an official door <a class="header-anchor" href="#_1-pick-an-official-door" aria-label="Permalink to &quot;1. Pick an official door&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Surface</th><th>How</th><th>Source</th></tr></thead><tbody><tr><td>Web</td><td>Open <a href="https://www.qianwen.com/" target="_blank" rel="noreferrer">qianwen.com</a>, click <strong>登录</strong></td><td>Home</td></tr><tr><td>Windows / macOS</td><td>Home <strong>下载电脑端</strong>, or open <a href="https://www.qianwen.com/download" target="_blank" rel="noreferrer">qianwen.com/download</a>; Windows also on <a href="https://apps.microsoft.com/detail/xp8m1sgl1lzr2f" target="_blank" rel="noreferrer">Microsoft Store · Qwen</a> (id <code>XP8M1SGL1LZR2F</code>)</td><td>Home, download page, Microsoft Store</td></tr><tr><td>iOS / iPad</td><td>App Store “千问 - 阿里AI助手” (id <code>6466733523</code>)</td><td><a href="https://apps.apple.com/cn/app/%E5%8D%83%E9%97%AE-%E9%98%BF%E9%87%8Cai%E5%8A%A9%E6%89%8B/id6466733523" target="_blank" rel="noreferrer">App Store</a></td></tr><tr><td>Android</td><td>Yingyongbao “千问”, package <code>com.aliyun.tongyi</code></td><td><a href="https://sj.qq.com/appdetail/com.aliyun.tongyi" target="_blank" rel="noreferrer">Yingyongbao</a></td></tr></tbody></table><p>The terms also name <strong>HarmonyOS</strong>, a <strong>browser plugin</strong>, a <strong>mini program</strong>, and <strong>H5</strong> (<a href="https://terms.alicdn.com/legal-agreement/terms/c_end_product_protocol/20231011201348415/20231011201348415.html" target="_blank" rel="noreferrer">user agreement</a> §1.1). No standalone official install page for those Qwen-assistant shapes was found on 2026-08-19. This tutorial does not invent steps. The Alibaba Cloud help article <a href="https://help.aliyun.com/zh/qwenwork/harmonyos-installation-guide" target="_blank" rel="noreferrer">QwenWork HarmonyOS guide</a> is a different product line. Do not treat it as the qianwen.com assistant install.</p><p>Login: agreement §5.1 says register with a phone number, or link a third-party account (Taobao, Alipay, Apple). That is a login method, not a Taobao tutorial.</p><p>The international site <a href="https://chat.qwen.ai/" target="_blank" rel="noreferrer">chat.qwen.ai</a> names itself <strong>Qwen Studio</strong>, with <strong>Log in / Sign up</strong>. It is not this page’s install path.</p><h3 id="_2-send-the-first-prompt" tabindex="-1">2. Send the first prompt <a class="header-anchor" href="#_2-send-the-first-prompt" aria-label="Permalink to &quot;2. Send the first prompt&quot;">​</a></h3><p>Logged-out home copy: 「你好，我是千问」. Top bar: <strong>API 服务</strong>, <strong>下载电脑端</strong>, <strong>登录</strong>. The model chip is <strong>Qwen3.7-千问</strong>.</p><p>After login, click <strong>新建对话</strong> and type in the box. The footer says continued use means you agree to the user agreement and privacy policy. Open those first.</p><p>Do not click top-bar <strong>API 服务</strong> to “start chatting”. That is the same-vendor API door. Its handbook is #85.</p><h3 id="_3-desktop-select-to-ask-and-the-sidebar" tabindex="-1">3. Desktop: select-to-ask and the sidebar <a class="header-anchor" href="#_3-desktop-select-to-ask-and-the-sidebar" aria-label="Permalink to &quot;3. Desktop: select-to-ask and the sidebar&quot;">​</a></h3><p>Install the desktop app only if you need an OS-level overlay. Official download-page title: <code>千问PC客户端 - 阿里AI助手</code>. Indexed download copy includes AI search, page summaries, AI PPT, image generation, PPT creation, voice notes, and select-to-ask translation.</p><p>User agreement §1.2: the Windows and Mac clients support web search and browsing, and a <strong>Qwen sidebar</strong> for chatting, summarizing, and asking while you browse.</p><p>Home banners also say:</p><table tabindex="0"><thead><tr><th>Action</th><th>Official wording</th></tr></thead><tbody><tr><td>Office assistant</td><td>Ships local-task capability; phone remote control, skills and connectors, multi-format delivery</td></tr><tr><td>Select-to-ask</td><td>Global efficiency tool; select on-screen text to summarize, translate, or create</td></tr><tr><td>Voice notes</td><td>Keeps recording offline; auto-organized notes</td></tr></tbody></table><p>Desktop shortcut keys: <strong>none</strong> were readable on a public page on 2026-08-19. Trust the client settings. Do not copy third-party blogs.</p><h2 id="official-capabilities-by-source" tabindex="-1">Official capabilities (by source) <a class="header-anchor" href="#official-capabilities-by-source" aria-label="Permalink to &quot;Official capabilities (by source)&quot;">​</a></h2><h3 id="home" tabindex="-1">Home <a class="header-anchor" href="#home" aria-label="Permalink to &quot;Home&quot;">​</a></h3><p><a href="https://www.qianwen.com/" target="_blank" rel="noreferrer">qianwen.com</a> shows:</p><ul><li>Sidebar: <strong>新建对话</strong>, <strong>云空间</strong>, <strong>AI创作</strong>, <strong>定时任务</strong></li><li>Modes: <strong>快速</strong>, <strong>办公助理</strong>, <strong>本地电脑</strong></li><li>Capability chips: PPT, AI video, AI image, code, translate, write, research, voice notes, gaokao, AV skim</li><li>Banners: office assistant, Qwen IME, voice notes, select-to-ask</li></ul><p><strong>本地电脑</strong> is a mode inside the product. It is not a prompt to install Tongyi Lingma.</p><h3 id="store-long-description" tabindex="-1">Store long description <a class="header-anchor" href="#store-long-description" aria-label="Permalink to &quot;Store long description&quot;">​</a></h3><p>App Store and Yingyongbao “About” matched on 2026-08-19:</p><ul><li>Q&amp;A with structured answers and a research mode</li><li>Office assistant that delivers web / app / PPT / Word / Excel / images, plus skills</li><li>Scheduled tasks: recurring or one-shot</li><li>Voice calls, 7×24</li><li>Agent plaza; <code>@</code> an agent in the thread</li><li>Life helper: takeout, hotels, restaurants, government services, shopping advice</li><li>Writing, AI PPT, in-thread editor (PDF / WORD / PPT / EXCEL conversion)</li><li>Docs: 10 files per upload, 500-page documents</li><li>Code: one-shot mini programs / pages / mini games / SQL; upload code or a screenshot to review</li><li>Live notes: offline or realtime speech-to-text</li><li>Create: Wan 2.7 video; Qwen-Image 2.0 generate / retouch</li><li>Study: classroom, photo homework, grading, a 500-million-item library</li></ul><p>That is <strong>chat and delivery</strong>, not clone-a-repo / open-a-PR / MCP. Repo-level coding is <a href="https://qoder.com.cn/" target="_blank" rel="noreferrer">Tongyi Lingma / Qoder CN</a> (site issue #84; no tutorial here).</p><p>Yingyongbao still has a “通义介绍” block that names Tongyi APP, dance/sing toys, Tingwu, and an in-app Lingma. Treat it as stale store copy, <strong>not</strong> the current feature list.</p><h3 id="qwen-ime" tabindex="-1">Qwen IME <a class="header-anchor" href="#qwen-ime" aria-label="Permalink to &quot;Qwen IME&quot;">​</a></h3><p>Home banner: a new Qwen IME app; 300 characters per minute, 9 dialects, no ads. Yingyongbao lists vendor app <code>com.qianwen.ime</code>. This tutorial does not write IME install steps.</p><h2 id="do-not-pick-a-winner-on-model-copy" tabindex="-1">Do not pick a winner on model copy <a class="header-anchor" href="#do-not-pick-a-winner-on-model-copy" aria-label="Permalink to &quot;Do not pick a winner on model copy&quot;">​</a></h2><p>Several official wordings existed on 2026-08-19:</p><table tabindex="0"><thead><tr><th>Source</th><th>Wording</th></tr></thead><tbody><tr><td>Home</td><td>Model chip <strong>Qwen3.7-千问</strong>; description says the strongest Qwen models</td></tr><tr><td>App Store</td><td>Latest / strongest Qwen models; create side names <strong>Wan 2.7</strong> and <strong>Qwen-Image 2.0</strong></td></tr><tr><td>Qwen Studio (international, not this tutorial)</td><td>On-page <strong>Qwen3.7-Plus</strong></td></tr><tr><td>Tongyi Lab</td><td>Model cards: Qwen3-Max / Qwen-Plus / Qwen-Flash and others</td></tr></tbody></table><p>Trust the names in your client. Do not write “the default is Qwen3.7”. Internals: <a href="/tech/fundamentals/LLM.html">Learn LLM</a>.</p><h2 id="legal-and-data" tabindex="-1">Legal and data <a class="header-anchor" href="#legal-and-data" aria-label="Permalink to &quot;Legal and data&quot;">​</a></h2><p>Open these before you rely on the product:</p><ul><li><a href="https://terms.alicdn.com/legal-agreement/terms/c_end_product_protocol/20231011201348415/20231011201348415.html" target="_blank" rel="noreferrer">Qwen user agreement</a> (updated 2026-03-20, effective 2026-03-27)</li><li><a href="https://terms.alicdn.com/legal-agreement/terms/privacy_policy_full/20231011201849846/20231011201849846.html" target="_blank" rel="noreferrer">Qwen privacy policy</a></li><li>In-app purchases also cite the <a href="https://terms.alicdn.com/legal-agreement/terms/c_end_product_protocol/20260728154300619/20260728154300619.html" target="_blank" rel="noreferrer">membership agreement</a></li></ul><p>The agreement names the website, web, clients (iOS, Android, Windows, Mac, HarmonyOS), browser plugin, mini program, and H5. This page does not paraphrase grant language.</p><p>Operator in the agreement: 上海智信普惠科技有限公司. Stated use: personal study, research, enjoyment, daily life, and entertainment.</p><p>Plans: App Store marks <strong>Free · In-App Purchases</strong>. <strong>No</strong> price table was found on qianwen.com. Do not invent numbers.</p><h2 id="pitfalls" tabindex="-1">Pitfalls <a class="header-anchor" href="#pitfalls" aria-label="Permalink to &quot;Pitfalls&quot;">​</a></h2><ul><li>Treating Qwen as Claude Code / Cursor. There is no official Qwen CLI or IDE plugin page. The coding tool is Tongyi Lingma / Qoder CN (#84).</li><li>Bookmarking <code>chat.qwen.ai</code> as “Qwen English”. That page’s product name is <strong>Qwen Studio</strong>.</li><li>Copying Yingyongbao’s “通义介绍” dance toys / Tingwu. Live home and App Store about-text do not repeat those columns.</li><li>Writing plugin / mini-program / HarmonyOS install steps with no official Qwen-assistant install URL.</li><li>Copying Bailian Token Plan prices into your notes. That is #85.</li><li>Turning a Taobao login into a Taobao tutorial. A login method is not the product scope.</li></ul><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="./qwen-cheatsheet.html">Cheatsheet</a></li><li><a href="./qwen-glossary.html">Glossary</a></li><li><a href="./">Learning map</a></li></ul>',50)])])}const w=t(r,[["render",i]]);export{f as __pageData,w as default};
